cd /tmp && python3 -c "
import datetime as dt
# Test with very large timedelta
huge_td = dt.timedelta(days=999999999)

# Try to subtract it from a datetime
now = dt.datetime.now()
try:
    date = now - huge_td
    print('Date:', date)
except Exception as e:
    print('Error on subtraction:', type(e).__name__, str(e))

# What about _abs_timedelta?
def _abs_timedelta(delta):
    if delta.days < 0:
        now = dt.datetime.now()
        return now - (now + delta)
    return delta

try:
    result = _abs_timedelta(huge_td)
    print('_abs_timedelta result:', result)
except Exception as e:
    print('Error in _abs_timedelta:', type(e).__name__, str(e))
"
